import select from '../../select.js';

// Tussey publishes no per-lift status anywhere (the only lift information on
// the site is an aggregate "Chair Lifts | 3" count), so this is trails only.
//
// The snow report is a hand-authored WYSIWYG block: three tables, of which the
// trail table is the only 3-column one (BASE CONDITIONS and MOUNTAIN STATS are
// 2-column). Selecting on row shape avoids the autogenerated CMS block id
// (#block--371), which is not stable.

// values are wrapped in arbitrarily nested <strong>/<em> and padded with
// non-breaking spaces, so take the whole descendant text and squash it
function cellText(node) {
  let out = '';
  const walk = n => {
    if (n.type === 'text') {
      out += n.data;
    }
    for (const child of n.children ?? []) {
      walk(child);
    }
  };
  walk(node);
  return out.replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
}

// free prose, not a vocabulary: 'Not open', 'closed for a rebuild' and
// 'closed (will open 12/13 and 12/14)' all miss coerce's map and would land on
// 'scheduled'. Note 'Not open' has to be tested before the /^open/ branch.
function normalizeStatus(status) {
  const s = status.toLowerCase();
  if (/^not\s*open/.test(s)) {
    return 'closed';
  }
  if (/^open/.test(s)) {
    return 'open';
  }
  if (/^closed/.test(s)) {
    return 'closed';
  }
  return status;
}

// 'Intermediate/Advanced' (currently the advanced terrain park) is not in the
// levels map; the rest - Easiest, Intermediate, Advanced - are.
function normalizeLevel(difficulty, name) {
  if (/terrain park/i.test(name)) {
    return 'terrainPark';
  }
  if (/intermediate\s*\/\s*advanced/i.test(difficulty)) {
    return 'black';
  }
  return difficulty;
}

export default function parse(dom) {
  const rows = [];
  for (const row of select(dom, 'table tr')) {
    const cells = select(row, 'td');
    if (cells.length !== 3) {
      continue;
    }
    const [name, difficulty, status] = cells.map(cellText);
    // header row
    if (!name || !status || /^slope$/i.test(name)) {
      continue;
    }
    rows.push({
      // a trailing '*' is the natural-snow-only footnote marker
      name: name.replace(/\*+$/, '').trim(),
      status: normalizeStatus(status),
      level: normalizeLevel(difficulty, name)
    });
  }
  return rows;
}
